create function public.create_rfq_atomic(p_title text,p_description text,p_currency char(3),p_items jsonb) returns uuid language plpgsql security invoker set search_path=public,pg_temp as $$ declare v_id uuid:=gen_random_uuid(); v_item jsonb; begin if auth.uid() is null then raise exception 'authentication required'; end if; insert into public.rfq_sessions(id,user_id,title,description,currency) values(v_id,auth.uid(),p_title,nullif(p_description,''),p_currency); for v_item in select value from jsonb_array_elements(p_items) loop insert into public.rfq_items(rfq_id,description,quantity,unit,specifications) values(v_id,v_item->>'description',(v_item->>'quantity')::numeric,v_item->>'unit',v_item->'specifications'); end loop; return v_id; end $$;
revoke all on function public.create_rfq_atomic(text,text,char(3),jsonb) from public,anon;
grant execute on function public.create_rfq_atomic(text,text,char(3),jsonb) to authenticated;
